for (const win of Services.wm.getEnumerator("")) {
  win.postMessage({ statusMessage, meteors }, "*");
}

this._progressBarContainer = document.getElementById(
  "statusbar-progresspanel"
);
this._throbber = document.getElementById("throbber-box");
this._activeProcesses = [];
this._statusQueue = [];

// make sure the stop button is accurate from the get-go
goUpdateCommand("cmd_stop");

window.addEventListener("message", event => {
  if (event.data.statusMessage) {
    this.showStatusString(event.data.statusMessage);
  } else {
    if (event.data.progress) {
      this.showProgress(event.data.progress);
    }
    if (event.data.meteors == "start-meteors") {
      this.startMeteors();
    } else if (event.data.meteors == "stop-meteors") {
      this.stopMeteors();
    }
  }
